method get_max_triples(n: int) returns (count: int)
    requires n > 0
    ensures count >= 0
    ensures count == CountValidTriples(a)
{
    var a := new int[n];
    var i: int;
    // Populate the array a with the specified values
    for i := 1 to n {
        a[i - 1] := i * i - i + 1;
    }

    // Compute the number of valid triples
    count := 0;
    var j, k: int;
    for i := 0 to n - 3 {
        for j := i + 1 to n - 2 {
            for k := j + 1 to n - 1 {
                if (a[i] + a[j] + a[k]) % 3 == 0 {
                    count := count + 1;
                }
            }
        }
    }
}

// Helper function to count valid triples
function CountValidTriples(a: seq<int>) : int
{
    var count := 0;
    var n := |a|; // length of the array
    var i, j, k: int;
    for i := 0 to n - 3 {
        for j := i + 1 to n - 2 {
            for k := j + 1 to n - 1 {
                if (a[i] + a[j] + a[k]) % 3 == 0 {
                    count := count + 1;
                }
            }
        }
    }
    return count;
}
